  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --color-primary: #171717;
      --color-accent: #0072F5;
      --color-accent-hover: #005BC4;
      --color-bg: #FAFAFA;
      --color-white: #FFFFFF;
      --color-gray-100: #F5F5F5;
      --color-gray-200: #E5E5E5;
      --color-gray-300: #D4D4D4;
      --color-gray-400: #A3A3A3;
      --color-gray-500: #737373;
      --color-gray-600: #525252;
      --color-gray-700: #404040;
      --color-gray-800: #262626;
      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
      --max-width: 1200px;
      --header-height: 64px;
    }

    body {
      font-family: var(--font-sans);
      background: var(--color-bg);
      color: var(--color-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }

    /* ===== HEADER ===== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--color-white);
      border-bottom: 1px solid var(--color-gray-200);
      height: var(--header-height);
    }

    .header-inner {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .header-left { display: flex; align-items: center; gap: 32px; }

    .logo {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 8px;
      white-space: nowrap;
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--color-primary);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 16px; height: 16px; }

    .logo-separator {
      width: 1px;
      height: 24px;
      background: var(--color-gray-300);
      margin: 0 4px;
    }

    .logo-blog {
      font-weight: 400;
      color: var(--color-gray-500);
    }

    .main-nav { display: flex; align-items: center; gap: 4px; }

    .nav-item {
      position: relative;
      padding: 8px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--color-gray-600);
      cursor: pointer;
      border-radius: 6px;
      transition: color 0.15s, background 0.15s;
      display: flex;
      align-items: center;
      gap: 4px;
      border: none;
      background: none;
      font-family: inherit;
    }

    .nav-item:hover { color: var(--color-primary); background: var(--color-gray-100); }

    .nav-item svg {
      width: 12px;
      height: 12px;
      transition: transform 0.2s;
    }

    .nav-item.active svg { transform: rotate(180deg); }

    .header-right { display: flex; align-items: center; gap: 12px; }

    .btn-ghost {
      padding: 7px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--color-gray-600);
      border: none;
      background: none;
      cursor: pointer;
      border-radius: 6px;
      font-family: inherit;
      transition: color 0.15s, background 0.15s;
    }

    .btn-ghost:hover { color: var(--color-primary); background: var(--color-gray-100); }

    .ask-ai {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 12px;
      font-size: 13px;
      font-weight: 500;
      color: var(--color-gray-600);
      border: 1px solid var(--color-gray-200);
      background: var(--color-white);
      cursor: pointer;
      border-radius: 6px;
      font-family: inherit;
      transition: border-color 0.15s, color 0.15s;
    }

    .ask-ai:hover { border-color: var(--color-gray-400); color: var(--color-primary); }

    .ask-ai svg { width: 14px; height: 14px; }

    .btn-signup {
      padding: 8px 16px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-white);
      background: var(--color-primary);
      border: none;
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
      transition: background 0.15s;
    }

    .btn-signup:hover { background: var(--color-gray-800); }

    /* Mega Menus */
    .mega-menu {
      position: absolute;
      top: calc(var(--header-height) - 1px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: 12px;
      box-shadow: 0 12px 40px rgba(0,0,0,0.08), 0 2px 8px rgba(0,0,0,0.04);
      padding: 24px 28px;
      display: none;
      min-width: 560px;
      z-index: 200;
      animation: menuFadeIn 0.15s ease;
    }

    @keyframes menuFadeIn {
      from { opacity: 0; transform: translateX(-50%) translateY(-4px); }
      to { opacity: 1; transform: translateX(-50%) translateY(0); }
    }

    .mega-menu.open { display: block; }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 24px;
    }

    .mega-menu-section h4 {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--color-gray-400);
      margin-bottom: 12px;
    }

    .mega-menu-section ul { list-style: none; }

    .mega-menu-section li { margin-bottom: 4px; }

    .mega-menu-section a {
      display: block;
      padding: 6px 8px;
      margin: 0 -8px;
      font-size: 14px;
      font-weight: 500;
      color: var(--color-gray-700);
      border-radius: 6px;
      transition: background 0.12s, color 0.12s;
    }

    .mega-menu-section a:hover { background: var(--color-gray-100); color: var(--color-primary); }

    .mega-menu-section a .menu-desc {
      display: block;
      font-size: 12px;
      font-weight: 400;
      color: var(--color-gray-400);
      margin-top: 1px;
    }

    /* Mobile hamburger */
    .mobile-toggle {
      display: none;
      border: none;
      background: none;
      cursor: pointer;
      padding: 8px;
    }

    .mobile-toggle span {
      display: block;
      width: 20px;
      height: 2px;
      background: var(--color-primary);
      margin: 4px 0;
      border-radius: 1px;
      transition: transform 0.2s, opacity 0.2s;
    }

    /* ===== MAIN CONTENT ===== */
    .main {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== HERO / PAGE TITLE ===== */
    .page-hero {
      padding: 56px 0 40px;
    }

    .page-hero h1 {
      font-size: 40px;
      font-weight: 800;
      letter-spacing: -1.2px;
      line-height: 1.15;
      color: var(--color-primary);
    }

    /* ===== CATEGORY FILTERS ===== */
    .filters-bar {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 0 0 32px;
      flex-wrap: wrap;
    }

    .filters-pills {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      flex: 1;
    }

    .pill {
      padding: 7px 16px;
      font-size: 13px;
      font-weight: 500;
      border: 1px solid var(--color-gray-200);
      background: var(--color-white);
      color: var(--color-gray-600);
      border-radius: 100px;
      cursor: pointer;
      transition: all 0.15s;
      font-family: inherit;
      white-space: nowrap;
    }

    .pill:hover { border-color: var(--color-gray-400); color: var(--color-primary); }

    .pill.active {
      background: var(--color-primary);
      color: var(--color-white);
      border-color: var(--color-primary);
    }

    .search-box {
      position: relative;
      width: 240px;
      flex-shrink: 0;
    }

    .search-box input {
      width: 100%;
      padding: 8px 14px 8px 36px;
      font-size: 14px;
      font-family: inherit;
      border: 1px solid var(--color-gray-200);
      border-radius: 8px;
      background: var(--color-white);
      color: var(--color-primary);
      outline: none;
      transition: border-color 0.15s;
    }

    .search-box input::placeholder { color: var(--color-gray-400); }
    .search-box input:focus { border-color: var(--color-accent); }

    .search-box svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--color-gray-400);
    }

    /* ===== FEATURED ARTICLES ===== */
    .featured-section {
      margin-bottom: 56px;
    }

    .featured-section h2 {
      font-size: 14px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--color-gray-400);
      margin-bottom: 20px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .featured-card {
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: 12px;
      padding: 32px;
      cursor: pointer;
      transition: border-color 0.2s, box-shadow 0.2s;
      display: flex;
      flex-direction: column;
    }

    .featured-card:hover {
      border-color: var(--color-gray-300);
      box-shadow: 0 4px 20px rgba(0,0,0,0.05);
    }

    .featured-card:first-child {
      grid-row: span 2;
    }

    .featured-card .card-meta {
      font-size: 13px;
      color: var(--color-gray-500);
      margin-bottom: 12px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .featured-card .card-meta .dot {
      width: 3px;
      height: 3px;
      border-radius: 50%;
      background: var(--color-gray-400);
    }

    .featured-card h3 {
      font-size: 24px;
      font-weight: 700;
      letter-spacing: -0.5px;
      line-height: 1.3;
      margin-bottom: 12px;
    }

    .featured-card:first-child h3 {
      font-size: 32px;
      letter-spacing: -0.8px;
    }

    .featured-card .card-excerpt {
      font-size: 15px;
      color: var(--color-gray-500);
      line-height: 1.6;
      flex: 1;
    }

    .featured-card .card-author {
      margin-top: 20px;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--color-gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 600;
      color: var(--color-gray-600);
      flex-shrink: 0;
    }

    .card-author .author-name {
      font-size: 14px;
      font-weight: 500;
    }

    /* Stats ribbon */
    .stats-ribbon {
      display: flex;
      gap: 24px;
      margin-top: 24px;
      padding-top: 20px;
      border-top: 1px solid var(--color-gray-200);
      flex-wrap: wrap;
    }

    .stat-item {
      flex: 1;
      min-width: 120px;
    }

    .stat-number {
      font-size: 22px;
      font-weight: 800;
      letter-spacing: -0.5px;
      color: var(--color-accent);
    }

    .stat-label {
      font-size: 12px;
      color: var(--color-gray-500);
      margin-top: 2px;
    }

    /* ===== LATEST NEWS ===== */
    .latest-section {
      margin-bottom: 56px;
    }

    .latest-section h2 {
      font-size: 14px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--color-gray-400);
      margin-bottom: 20px;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
    }

    .news-card {
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: 12px;
      padding: 24px;
      cursor: pointer;
      transition: border-color 0.2s, box-shadow 0.2s;
      display: flex;
      flex-direction: column;
    }

    .news-card:hover {
      border-color: var(--color-gray-300);
      box-shadow: 0 4px 20px rgba(0,0,0,0.05);
    }

    .news-card .card-tag {
      display: inline-block;
      padding: 3px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      border-radius: 100px;
      margin-bottom: 14px;
      align-self: flex-start;
    }

    .tag-general { background: #EEF4FF; color: #3B6FD4; }
    .tag-engineering { background: #F0FDF4; color: #22863A; }
    .tag-customers { background: #FFF7ED; color: #C2410C; }
    .tag-community { background: #FDF4FF; color: #9333EA; }
    .tag-company { background: #FFF1F2; color: #BE123C; }
    .tag-security { background: #FEF9C3; color: #A16207; }
    .tag-changelog { background: #F0F9FF; color: #0369A1; }
    .tag-press { background: #F5F5F4; color: #57534E; }
    .tag-v0 { background: #F0FDFA; color: #0D9488; }

    .news-card .card-date {
      font-size: 12px;
      color: var(--color-gray-400);
      margin-bottom: 10px;
    }

    .news-card h3 {
      font-size: 17px;
      font-weight: 700;
      letter-spacing: -0.3px;
      line-height: 1.35;
      margin-bottom: 8px;
    }

    .news-card .card-excerpt {
      font-size: 14px;
      color: var(--color-gray-500);
      line-height: 1.55;
      flex: 1;
    }

    .news-card .card-author {
      margin-top: 16px;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .news-card .author-name {
      font-size: 13px;
      font-weight: 500;
    }

    /* No results */
    .no-results {
      display: none;
      text-align: center;
      padding: 60px 20px;
      color: var(--color-gray-500);
      font-size: 15px;
      grid-column: 1 / -1;
    }

    .no-results.visible { display: block; }

    /* Show more */
    .show-more-wrapper {
      text-align: center;
      padding: 32px 0;
    }

    .btn-show-more {
      padding: 12px 32px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-primary);
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
      transition: border-color 0.15s, background 0.15s;
    }

    .btn-show-more:hover { border-color: var(--color-gray-400); background: var(--color-gray-100); }
    .btn-show-more:disabled { opacity: 0.5; cursor: default; }

    /* ===== CTA BANNER ===== */
    .cta-section {
      margin-bottom: 80px;
    }

    .cta-banner {
      background: var(--color-primary);
      border-radius: 16px;
      padding: 56px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
      align-items: center;
    }

    .cta-main h2 {
      font-size: 32px;
      font-weight: 800;
      letter-spacing: -0.8px;
      color: var(--color-white);
      line-height: 1.2;
      margin-bottom: 8px;
    }

    .cta-main p {
      font-size: 15px;
      color: var(--color-gray-400);
      margin-bottom: 24px;
      line-height: 1.6;
    }

    .cta-buttons { display: flex; gap: 12px; flex-wrap: wrap; }

    .btn-cta-primary {
      padding: 12px 24px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-primary);
      background: var(--color-white);
      border: none;
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
      transition: background 0.15s;
    }

    .btn-cta-primary:hover { background: var(--color-gray-200); }

    .btn-cta-secondary {
      padding: 12px 24px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-gray-300);
      background: transparent;
      border: 1px solid var(--color-gray-600);
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
      transition: border-color 0.15s, color 0.15s;
    }

    .btn-cta-secondary:hover { border-color: var(--color-gray-400); color: var(--color-white); }

    .cta-enterprise {
      background: var(--color-gray-800);
      border-radius: 12px;
      padding: 32px;
    }

    .cta-enterprise h3 {
      font-size: 18px;
      font-weight: 700;
      color: var(--color-white);
      margin-bottom: 8px;
    }

    .cta-enterprise p {
      font-size: 14px;
      color: var(--color-gray-400);
      margin-bottom: 20px;
      line-height: 1.55;
    }

    .btn-enterprise {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-white);
      background: var(--color-accent);
      border: none;
      border-radius: 8px;
      cursor: pointer;
      font-family: inherit;
      transition: background 0.15s;
    }

    .btn-enterprise:hover { background: var(--color-accent-hover); }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--color-primary);
      color: var(--color-gray-400);
      padding: 64px 0 32px;
    }

    .footer-inner {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 13px;
      font-weight: 600;
      color: var(--color-white);
      margin-bottom: 14px;
    }

    .footer-col ul { list-style: none; }

    .footer-col li {
      margin-bottom: 8px;
    }

    .footer-col a {
      font-size: 13px;
      color: var(--color-gray-400);
      transition: color 0.15s;
    }

    .footer-col a:hover { color: var(--color-white); }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 24px;
      border-top: 1px solid var(--color-gray-700);
      font-size: 13px;
    }

    .footer-status {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .status-dot {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #22C55E;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr; }
      .featured-card:first-child { grid-row: auto; }
      .featured-card:first-child h3 { font-size: 24px; }
      .news-grid { grid-template-columns: repeat(2, 1fr); }
      .cta-banner { grid-template-columns: 1fr; }
    }

    @media (max-width: 768px) {
      .page-hero h1 { font-size: 28px; }

      .main-nav, .header-right .ask-ai, .header-right .btn-ghost { display: none; }
      .mobile-toggle { display: block; }

      .filters-bar { flex-direction: column; align-items: stretch; }
      .search-box { width: 100%; }

      .news-grid { grid-template-columns: 1fr; }

      .cta-banner { padding: 32px; }
      .cta-main h2 { font-size: 24px; }

      .footer-grid { grid-template-columns: repeat(2, 1fr); }

      .mega-menu { display: none !important; }
